class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self.monthly_limit_bytes = monthly_limit_mib * 1024 * 1024
        # Store uploads per month: {month: {filename: size_bytes}}
        self.uploads = {}

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0")

        # Initialize month entry if it doesn't exist
        if month not in self.uploads:
            self.uploads[month] = {}

        # If file already exists in this month, no change needed
        if name in self.uploads[month]:
            return

        # Calculate current usage for this month
        current_usage = sum(self.uploads[month].values())

        # Check if adding this file would exceed the limit
        if current_usage + size_bytes > self.monthly_limit_bytes:
            raise ValueError("Upload would exceed monthly quota")

        # Add the file to this month's uploads
        self.uploads[month][name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        # Only remove if the month and file exist
        if month in self.uploads and name in self.uploads[month]:
            del self.uploads[month][name]

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        if month not in self.uploads:
            return 0
        return sum(self.uploads[month].values())
